def diagram():
    labels=[('01','Исходный запрос','Цитата и контекст'),('02','Задача','Границы и критерии'),('03','Проверка кода','Точная ревизия'),('04','Интеграция','Реальный сценарий'),('05','Приёмка','Проверяемый результат')]
    parts=['<figure class="diagram"><svg viewBox="0 0 950 180" role="img" aria-label="От исходного запроса к подтверждённой приёмке"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#7c9c91"/></marker></defs>']
    for i,(num,title,sub) in enumerate(labels):
        x=10+i*190
        if i<4:parts.append(f'<path d="M{x+166} 70H{x+188}" stroke="#7c9c91" stroke-width="1.8" marker-end="url(#arrow)"/>')
        parts.append(f'<rect x="{x}" y="25" width="166" height="93" rx="10" fill="white" stroke="#bfd0c8"/><text x="{x+13}" y="48" fill="#548573" font-size="10" font-family="system-ui">{num}</text><text x="{x+13}" y="72" fill="#22382f" font-size="12" font-weight="600" font-family="system-ui">{title}</text><text x="{x+13}" y="95" fill="#718279" font-size="10" font-family="system-ui">{sub}</text>')
    parts.append('<path d="M680 121 V150 H270 V124" fill="none" stroke="#b5904c" stroke-dasharray="4 4" marker-end="url(#arrow)"/><text x="355" y="171" fill="#947641" font-size="10" font-family="system-ui">Ошибка или недостаточно доказательств → задача остаётся открытой</text></svg><figcaption>Схема процесса приёмки, а не доказательство прохождения конкретной задачи. Результаты тестов и источник реализации указаны отдельно.</figcaption></figure>')
    return ''.join(parts)


def render_markdown(text):
    # Normalise generated table rows while retaining all source text in git.
    text=re.sub(r'(?m)(^\|[^\n]*\|)\n\n(?=\|)',r'\1\n',text)
    text=re.sub(r'(?m)(^\|[^\n]*\|)\n\n(?=\|)',r'\1\n',text)
    # Raw source HTML is never executable. Our limited details wrappers are
    # converted to ordinary Markdown headings; source quotations stay intact.
    text=re.sub(r'<details><summary>(.*?)</summary>',r'\n\n**\1**\n\n',text)
    text=text.replace('</details>','')
    result=md.render(text)
    result=re.sub(r'<pre><code class="language-mermaid">.*?</code></pre>',lambda m:diagram()+'<details><summary>Редактируемый исходник диаграммы Mermaid</summary>'+m.group()+'</details>',result,flags=re.S)
    # Relative source assets do not magically exist on this alternate site.
    # Resolve documentation links to their exact source file in GitHub instead.
    return result


def main():
    OUT.mkdir(exist_ok=True)
    summary=json.loads((BASE/'corpus-summary.json').read_text())
    tests=json.loads((BASE/'test-results.json').read_text())
    q=json.loads((BASE/'quote-registry.json').read_text())
    all_rows=[]
    for p in sorted((BASE/'issues').glob('*.json')):
        for row in json.loads(p.read_text()):
            all_rows.append({k:row[k] for k in ('key','repo','number','title','provider_state','topic','classification','provenance','quote_ids','source_sha','verification_disposition','verification_flags','canonical')})
    documents=[]
    for p in sorted(SPECS.rglob('*.md')):
        text=p.read_text();ident=str(p.relative_to(SPECS))[:-3]
        title=re.search(r'^# (.+)',text,re.M)
        title=title.group(1) if title else p.stem
        documents.append({'id':ident,'title':title,'path':str(p),'kind':'contract' if p.parent==SPECS else 'source-review','html':render_markdown(text),'search':re.sub(r'\s+',' ',text)})
    data={'summary':summary,'tests':tests,'quotes':q['records'],'excluded':q['excluded_records'],'issues':all_rows,'documents':documents,'git':GIT,'doc':DOC,'root':ROOT}
    payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
    javascript=r'''
const D=JSON.parse(document.getElementById('data').textContent), M=document.querySelector('main');let page=0;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const keyUrl=k=>D.git+k.replace('#','/issues/');
const groups={intake:'Задачи и доказательства',worktrees:'Worktree и сохранность работы',identity:'Идентичность и guards',shipping:'Ship и локальные проверки',roles:'Роли, модели и маршруты',health:'Квоты и состояние аккаунтов',execution:'Выполнение и восстановление',telegram:'Telegram и разрешения',resources:'Ресурсы и процессы',telemetry:'Статистика и dashboards',specs:'Спецификации и review',provisioning:'Конфигурация и установка',testing:'Проверки и приёмка',auxiliary:'Остальные CLI',process:'Процессные записи'};
function chip(t,c=''){return '<span class="chip '+c+'">'+E(t)+'</span>'}
function title(k,t,intro=''){return '<div class="eyebrow">'+E(k)+'</div><h1>'+E(t)+'</h1>'+(intro?'<p class="intro">'+E(intro)+'</p>':'')}
function nav(){let route=location.hash||'#/';document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',route===a.getAttribute('href')));document.querySelector('aside').classList.remove('open')}
function counts(){return '<div class="stats"><div class="stat"><strong>'+D.issues.length.toLocaleString('ru')+'</strong><span>issues · все состояния</span></div><div class="stat"><strong>'+D.summary.public_prs+'</strong><span>PR · история реализации</span></div><div class="stat"><strong>'+D.documents.length+'</strong><span>документов в каталоге</span></div><div class="stat"><strong>'+D.quotes.length+'</strong><span>записей с атрибуцией источника</span></div></div>'}
function home(){M.innerHTML=title('RIG / RECOVERY REVIEW','От запроса — к работающему результату','Спецификации, исходные запросы и повторные проверки всей экосистемы. Закрытая задача и влитый PR не приравниваются к подтверждённой работоспособности.')+counts()+'<div class="notice"><strong>Что подтверждено:</strong> полная публичная инвентаризация и изолированные тесты на зафиксированных ревизиях. <strong>Что нельзя из этого заключить:</strong> что все функции работают на пользовательской машине. Приватный harness-cli и непроверенные live-сценарии выделены отдельно.</div><div class="reviewbar"><a class="button" href="#/specs">Открыть все спецификации</a><a class="button secondary" href="#/backlog">Разобрать backlog</a><a class="button secondary" href="'+D.root+'" target="_blank" rel="noopener">Эпик восстановления ↗</a></div>'+document.getElementById('flow').innerHTML+'<h2>Контракты и направления</h2><div class="grid">'+Object.entries(groups).map(([id,t])=>'<a class="card" href="#/spec/'+id+'"><span class="key">'+E(id)+'</span><h3>'+E(t)+'</h3><p>'+D.issues.filter(i=>i.topic===id).length+' связанных задач · исходные цитаты · пример · проверка</p></a>').join('')+'</div>'+foot()}
function foot(){return '<footer>Публичное чтение. Комментарии к задачам и предложения исправлений отправляются через GitHub с его авторизацией. Этот сайт не заявляет ограничение чтения по GitHub или @glide.vc. Исходники приватных репозиториев и сторонние клиентские переписки не опубликованы. Срез: 10 сентября 2026; статусы в GitHub могли измениться после чтения.</footer>'}
function specs(){M.innerHTML=title('КАТАЛОГ','Все спецификации','Текущие контракты восстановления и сохранённые исходные документы. Прежние статусы Draft / Skipped не превращены в Approved.')+'<div class="toolbar"><input id="search" placeholder="Найти спецификацию или термин…" aria-label="Поиск спецификации"><select id="kind" aria-label="Тип документа"><option value="">Все документы</option><option value="contract">Контракты восстановления</option><option value="source-review">Исходные спецификации с ревью</option></select></div><div id="results" class="grid"></div>'+foot();let show=()=>{let s=document.querySelector('#search').value.toLowerCase(),k=document.querySelector('#kind').value;let rows=D.documents.filter(d=>(!k||d.kind===k)&&(!s||(d.title+' '+d.search).toLowerCase().includes(s)));document.querySelector('#results').innerHTML=rows.map(d=>'<a class="card" href="#/spec/'+encodeURIComponent(d.id)+'"><span class="key">'+E(d.kind==='contract'?'Recovery contract':'Source + review')+'</span><h3>'+E(d.title)+'</h3><p>'+E(d.path)+'</p></a>').join('')||'<div class="empty">Нет совпадений</div>'};document.querySelector('#search').oninput=show;document.querySelector('#kind').onchange=show;show()}
function spec(id){let d=D.documents.find(x=>x.id===id);if(!d){M.innerHTML=title('404','Документ не найден')+'<a href="#/specs">Вернуться к каталогу</a>';return}M.innerHTML='<div class="breadcrumbs"><a href="#/specs">Спецификации</a> / '+E(d.id)+'</div><div class="reviewbar"><a class="button" id="review" target="_blank" rel="noopener">Предложить правку через GitHub ↗</a><a class="button secondary" href="'+D.doc+d.path+'" target="_blank" rel="noopener">Исходный Markdown ↗</a><button class="button secondary" id="copy">Копировать контекст ревью</button></div><div class="readmeta"><span>Статус: контракт / ревью, не подтверждение реализации</span><span>Источник: git · 2026-09-10</span></div><article class="document">'+d.html+'</article>'+foot();let context='Спецификация: '+d.title+'\nИсточник: '+D.doc+d.path+'\nРаздел / цитата:\n\nОжидаемое поведение:\n\nЗамечание и пример:\n\nСвязанные задачи:\n';document.querySelector('#review').href=D.git+'rig-cli/issues/new?title='+encodeURIComponent('[Spec review] '+d.title.slice(0,100))+'&body='+encodeURIComponent(context);document.querySelector('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(context);document.querySelector('#copy').textContent='Скопировано'}catch{document.querySelector('#copy').textContent='Буфер недоступен; используйте ссылку GitHub'}};document.querySelectorAll('.document a').forEach(a=>{let href=a.getAttribute('href')||'';if(href.startsWith('../')||href.startsWith('./'))a.href=D.doc+d.path.substring(0,d.path.lastIndexOf('/')+1)+href;if(/^https:/.test(a.href)){a.target='_blank';a.rel='noopener'}})}
function backlog(){page=0;M.innerHTML=title('ПОЛНЫЙ РЕЕСТР','Backlog и доказательства','Каждая строка хранит исходный статус отдельно от результата повторной проверки. «Источник не найден» не заполняется выдуманной цитатой.')+'<div class="toolbar"><input id="search" placeholder="Номер, описание, симптом…" aria-label="Поиск задачи"><select id="repo" aria-label="Репозиторий"><option value="">Все репозитории</option>'+Object.keys(D.tests).sort().map(r=>'<option>'+E(r)+'</option>').join('')+'</select><select id="state" aria-label="Состояние"><option value="">Все состояния</option><option value="open">Открытые</option><option value="closed">Закрытые в источнике</option><option value="gap">Нет исходного запроса</option><option value="process">Процессные записи</option></select></div><div id="count" class="result-count"></div><div id="results"></div><div class="pager"><button class="button secondary" id="prev">← Назад</button><span id="page"></span><button class="button secondary" id="next">Далее →</button></div>'+foot();let rows=[];let show=()=>{let s=document.querySelector('#search').value.toLowerCase(),r=document.querySelector('#repo').value,t=document.querySelector('#state').value;rows=D.issues.filter(i=>(!r||i.repo===r)&&(!s||(i.key+' '+i.title).toLowerCase().includes(s))&&(!t||(t==='gap'?i.provenance.includes('source-gap'):t==='process'?i.classification==='process-record':i.provider_state===t)));page=Math.min(page,Math.max(0,Math.ceil(rows.length/40)-1));document.querySelector('#count').textContent=rows.length+' задач';document.querySelector('#results').innerHTML=rows.slice(page*40,(page+1)*40).map(i=>'<div class="row"><div class="rowmeta"><a href="'+keyUrl(i.key)+'" target="_blank" rel="noopener">'+E(i.key)+' ↗</a><span>'+E(i.provider_state)+'</span><a href="#/spec/'+i.topic+'">'+E(groups[i.topic])+'</a></div><h3>'+E(i.title)+'</h3><div class="chips">'+chip(i.classification)+chip(i.provenance.includes('source-gap')?'Исходный запрос: пробел':'Есть связанный источник',i.provenance.includes('source-gap')?'warn':'')+chip('Live-приёмка не подтверждена','warn')+'</div><small>Исходник '+E(i.source_sha.slice(0,12))+' · '+E(i.quote_ids.map(x=>'Q'+x).join(', '))+(i.canonical?' · Каноническая задача: '+E(i.canonical):'')+'</small>'+(i.verification_flags.length?'<details><summary>Проверить доказательства ('+i.verification_flags.length+')</summary>'+i.verification_flags.map(f=>'<p>'+E(f)+'</p>').join('')+'</details>':'')+'</div>').join('')||'<div class="empty">Нет совпадений</div>';document.querySelector('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/40));document.querySelector('#prev').disabled=page===0;document.querySelector('#next').disabled=(page+1)*40>=rows.length};['search','repo','state'].forEach(id=>document.getElementById(id).oninput=()=>{page=0;show()});document.querySelector('#prev').onclick=()=>{page--;show()};document.querySelector('#next').onclick=()=>{page++;show()};show()}
function quotes(){M.innerHTML=title('ПРОИСХОЖДЕНИЕ ТРЕБОВАНИЙ','Исходные запросы','Отредактированная цитата показана рядом с оригиналом, источником и контекстом. Заголовки, созданные агентами, не приписаны пользователю.')+'<div class="notice">145 записей экспорта исключены из публикации цитат: сгенерированные названия задач, пересказы агентов и сообщения о стороннем клиентском проекте. Фрагменты не считаются самостоятельным разрешением на действие.</div><div class="toolbar"><input id="search" placeholder="Искать по цитате, ID или контексту…" aria-label="Поиск исходного запроса"></div><div id="results"></div>'+foot();let show=()=>{let s=document.querySelector('#search').value.toLowerCase();document.querySelector('#results').innerHTML=D.quotes.filter(q=>!s||('Q'+q.id+' '+q.edited+' '+q.context).toLowerCase().includes(s)).map(q=>'<div class="row"><div class="rowmeta"><strong>Q'+E(q.id)+'</strong><span>'+E(q.source_kind)+'</span></div><blockquote class="quote">'+E(q.edited).replace(/\n/g,'<br>')+'</blockquote><small>'+E(q.context)+(q.pages&&q.pages.length?' · PDF: '+E(q.pages.join(', ')):'')+'</small>'+(q.context_incomplete?'<div class="chips">'+chip('Контекст неполный; не самостоятельное разрешение','warn')+'</div>':'')+'<details><summary>Оригинал до редакторской правки</summary><p>'+E(q.original).replace(/\n/g,'<br>')+'</p></details></div>').join('')};document.querySelector('#search').oninput=show;show()}
function evidence(){M.innerHTML=title('ПОВТОРНЫЕ ПРОВЕРКИ','Что действительно запускалось','Каждый результат относится к указанной ревизии и окружению. Падения из-за зависимостей, нестабильность теста и ошибка продукта — разные выводы.')+'<div class="notice">Первый полный прогон не установил ImageMagick 7. Визуальные ошибки review-cli нельзя считать отдельными багами продукта. Дополнительные прогоны с корректными зависимостями и повторением нестабильных тестов опубликованы в отдельном workflow.</div><div class="reviewbar"><a class="button" href="https://github.com/alex-mextner/rig-cli/actions/runs/34476344921" target="_blank" rel="noopener">Первый полный прогон ↗</a><a class="button secondary" href="https://github.com/alex-mextner/rig-cli/actions/runs/34478551966" target="_blank" rel="noopener">Повторная проверка причин ↗</a></div><div class="tablewrap"><table class="evidence"><thead><tr><th>Репозиторий</th><th>SHA</th><th>Passed</th><th>Failed</th><th>Skipped</th></tr></thead><tbody>'+Object.entries(D.tests).map(([r,t])=>'<tr><td>'+E(r)+'</td><td><a href="'+D.git+r+'/tree/'+t.source_sha+'" target="_blank" rel="noopener">'+E(t.source_sha.slice(0,12))+'</a></td><td>'+(t.test_counts.passed||0)+'</td><td class="badnum">'+(t.test_counts.failed||0)+'</td><td>'+(t.test_counts.skipped||0)+'</td></tr>').join('')+'</tbody></table></div><h2>Границы доказательств</h2><p>Тесты работали в изолированном HOME без операторских токенов и реальных Telegram-карточек. Приватный harness-cli не входит в эту публичную матрицу. macOS, реальные native-события, PATH установленного бинарника и пользовательские UI-сценарии требуют собственных доказательств.</p><a class="button secondary" href="'+D.doc+'docs/grooming/full-2026-09-10/test-results.json" target="_blank" rel="noopener">Машиночитаемый журнал ↗</a>'+foot()}
function route(){nav();let h=(location.hash||'#/').slice(2);if(h.startsWith('spec/'))spec(decodeURIComponent(h.slice(5)));else if(h==='specs')specs();else if(h==='backlog')backlog();else if(h==='quotes')quotes();else if(h==='evidence')evidence();else home();window.scrollTo({top:0});document.title=(h.startsWith('spec/')?'Spec review':'Rig / Recovery review');M.focus({preventScroll:true})}
window.addEventListener('hashchange',route);document.getElementById('menu').onclick=()=>document.querySelector('aside').classList.toggle('open');route();
'''
    nav=''.join('<a data-route class="navitem" href="'+href+'">'+label+'</a>' for href,label in [('#/','Обзор восстановления'),('#/specs','Все спецификации'),('#/backlog','Полный backlog'),('#/quotes','Исходные запросы'),('#/evidence','Результаты проверок')])
    nav+='<div class="navlabel">Контракты</div>'+''.join('<a data-route class="navitem" href="#/spec/'+name+'">'+html.escape(title)+'</a>' for name,title in [('identity','Идентичность агентов'),('worktrees','Изоляция worktree'),('roles','Роли и модели'),('health','Квоты и health'),('telegram','Telegram и approvals'),('intake','Задачи и доказательства'),('specs','Spec review')])
    page='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta name="color-scheme" content="light"><title>Rig / Recovery review</title><style>'+CSS+'</style></head><body><header><a class="brand" href="#/"><span class="mark">r</span>rig <span style="font-weight:400;color:#7b8790">/ review</span></a><span class="header-meta">Source → contract → evidence · 10 Sep 2026</span><button id="menu" class="button secondary mobilemenu" aria-label="Открыть навигацию">Меню</button><a class="button secondary" href="'+ROOT+'" target="_blank" rel="noopener">GitHub ↗</a></header><div class="shell"><aside><div class="navlabel">Recovery workspace</div>'+nav+'<div class="navlabel">Публикация</div><p style="font-size:11px;padding:0 12px;color:#647182">Публичное чтение.<br>Ревью через GitHub.<br>Не production-аттестация.</p></aside><main tabindex="-1"></main></div><template id="flow">'+diagram()+'</template><script type="application/json" id="data">'+payload+'</script><script>'+javascript+'</script></body></html>'
    assert '<script src=' not in page
    assert len(documents)>=40
    (OUT/'index.html').write_text(page)
    (OUT/'README.md').write_text('# Rig recovery review portal\n\nSelf-contained public HTML reader. All styles and diagrams are inline; no font files, remote JS or credentials are included. Review submissions use GitHub issue creation and its authentication. Reading is public, not restricted by OAuth/domain.\n\nRebuild with the source-verified grooming workflow.\n')
    (OUT/'manifest.json').write_text(json.dumps({'documents':len(documents),'public_issues':len(all_rows),'quote_records':len(q['records']),'bytes':len(page.encode()),'auth':'public-reader; GitHub-authenticated review submission','private_source_included':False},indent=2))
    print('Rendered portal:',len(documents),'documents;',len(page.encode()),'bytes')

if __name__=='__main__':main()
